WITH single_bonds AS (
  SELECT atom1_id AS atom_id FROM bond WHERE type = '-'
  UNION
  SELECT atom2_id AS atom_id FROM bond WHERE type = '-'
), iodine_atoms AS (
  SELECT DISTINCT id AS atom_id FROM atom WHERE element = 'I'
), sulfur_atoms AS (
  SELECT DISTINCT id AS atom_id FROM atom WHERE element = 'S'
), iodine_in_bonds AS (
  SELECT atom_id FROM single_bonds
  WHERE atom_id IN (SELECT atom_id FROM iodine_atoms)
), sulfur_in_bonds AS (
  SELECT atom_id FROM single_bonds
  WHERE atom_id IN (SELECT atom_id FROM sulfur_atoms)
)
SELECT 
  (SELECT COUNT(DISTINCT atom_id) FROM iodine_in_bonds) AS distinct_iodine_atoms,
  (SELECT COUNT(DISTINCT atom_id) FROM sulfur_in_bonds) AS distinct_sulfur_atoms
;

